def is_palindrome(s: str) -> bool:
    """Return True if s reads the same backwards (ignoring case, spaces and punctuation)."""
    # Remove all non-letter and digit characters
    chars = ''.join(char for char in s if char.isalnum())

    # Check if the string is empty or has only one character
    if not chars or len(chars) == 1:
        return True

    # Compare characters from the start and end moving towards the center
    for i in range(len(chars) // 2):
        if chars[i] != chars[len(chars) - i - 1]:
            return False

    return True

